+const wordsIn = (text) => String(text).match(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu) ?? [];
+
+/**
+ * Count word-like Unicode tokens.
+ * @param {string} text
+ * @returns {number}
+ */
+export function wordCount(text) {
+  return wordsIn(text).length;
+}
+
+/**
+ * Count non-empty sentence-like segments.
+ * @param {string} text
+ * @returns {number}
+ */
+export function sentenceCount(text) {
+  return String(text)
+    .split(/[.!?。！？]+/u)
+    .filter((segment) => wordsIn(segment).length > 0).length;
+}
+
+/**
+ * Count each Unicode character, including whitespace and punctuation.
+ * @param {string} text
+ * @returns {Record<string, number>}
+ */
+export function charFrequency(text) {
+  return Object.fromEntries(
+    [...String(text)].reduce((counts, character) => {
+      counts.set(character, (counts.get(character) ?? 0) + 1);
+      return counts;
+    }, new Map()),
+  );
+}
+
+/**
+ * Return a rounded-up reading-time estimate.
+ * @param {string} text
+ * @param {number} [wpm=200]
+ * @returns {number}
+ */
+export function readingTimeMinutes(text, wpm = 200) {
+  if (!Number.isFinite(wpm) || wpm <= 0) {
+    throw new RangeError("wpm must be a positive finite number");
+  }
+
+  return Math.ceil(wordCount(text) / wpm);
+}
+
+/**
+ * Return the most frequent words, case-insensitively.
+ * @param {string} text
+ * @param {number} [n=10]
+ * @returns {{word: string, count: number}[]}
+ */
+export function topWords(text, n = 10) {
+  if (!Number.isInteger(n) || n < 0) {
+    throw new RangeError("n must be a non-negative integer");
+  }
+
+  const counts = new Map();
+  for (const word of wordsIn(text)) {
+    const normalized = word.toLowerCase();
+    counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
+  }
+
+  return [...counts]
+    .map(([word, count]) => ({ word, count }))
+    .sort((left, right) => right.count - left.count || left.word.localeCompare(right.word))
+    .slice(0, n);
+}
