+#!/usr/bin/env node
+
+import { readFile } from "node:fs/promises";
+import process from "node:process";
+
+import {
+  charFrequency,
+  readingTimeMinutes,
+  sentenceCount,
+  topWords,
+  wordCount,
+} from "./lib.mjs";
+
+const usage = `Usage: node cli.mjs [file] [--json] [--top <n>]
+
+Read text from a file or standard input, then print summary statistics.
+
+Options:
+  --json       Print a JSON object.
+  --top <n>    Include the top n words (default: 10).
+  -h, --help   Show this help text.
+`;
+
+function parseArguments(arguments_) {
+  const options = { file: undefined, json: false, top: 10 };
+
+  for (let index = 0; index < arguments_.length; index += 1) {
+    const argument = arguments_[index];
+
+    if (argument === "--json") {
+      options.json = true;
+    } else if (argument === "--top") {
+      const value = arguments_[index + 1];
+      if (!/^\d+$/u.test(value ?? "")) {
+        throw new Error("--top must be a non-negative integer");
+      }
+      options.top = Number(value);
+      index += 1;
+    } else if (argument === "--help" || argument === "-h") {
+      options.help = true;
+    } else if (argument.startsWith("-") && argument !== "-") {
+      throw new Error(`Unknown option: ${argument}`);
+    } else if (options.file === undefined) {
+      options.file = argument;
+    } else {
+      throw new Error("Provide at most one input file");
+    }
+  }
+
+  return options;
+}
+
+async function readInput(file) {
+  return file === undefined || file === "-" ? readFile(0, "utf8") : readFile(file, "utf8");
+}
+
+function summarize(text, top) {
+  return {
+    characters: [...text].length,
+    words: wordCount(text),
+    sentences: sentenceCount(text),
+    readingTimeMinutes: readingTimeMinutes(text),
+    topWords: topWords(text, top),
+    charFrequency: charFrequency(text),
+  };
+}
+
+function formatSummary(summary) {
+  const lines = [
+    `Characters: ${summary.characters}`,
+    `Words: ${summary.words}`,
+    `Sentences: ${summary.sentences}`,
+    `Reading time: ${summary.readingTimeMinutes} minute(s)`,
+    "Top words:",
+  ];
+
+  lines.push(
+    ...(summary.topWords.length === 0
+      ? ["  (none)"]
+      : summary.topWords.map(({ word, count }) => `  ${word}: ${count}`)),
+  );
+
+  return lines.join("\n");
+}
+
+try {
+  const options = parseArguments(process.argv.slice(2));
+  if (options.help) {
+    process.stdout.write(usage);
+  } else {
+    const summary = summarize(await readInput(options.file), options.top);
+    process.stdout.write(`${options.json ? JSON.stringify(summary, null, 2) : formatSummary(summary)}\n`);
+  }
+} catch (error) {
+  process.stderr.write(`textstat: ${error.message}\n`);
+  process.stderr.write(usage);
+  process.exitCode = 1;
+}
